from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # The marker color appears as many separate single-cell components.
    candidates = []
    for color in counts:
        if color == bg:
            continue
        seen = set()
        isolated = 0
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                q = [(r, c)]
                seen.add((r, c))
                for x, y in q:
                    for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                        if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx,ny) not in seen:
                            seen.add((nx, ny))
                            q.append((nx, ny))
                if len(q) == 1:
                    isolated += 1
        candidates.append((isolated, counts[color], color))
    marker = max(candidates)[2]

    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]

    # Find the largest connected component made of the template's non-background,
    # non-marker cells.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (bg, marker) or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            for x, y in q:
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if (0 <= nx < h and 0 <= ny < w and
                        grid[nx][ny] not in (bg, marker) and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            components.append(q)

    template = max(components, key=len)
    r0 = min(r for r, c in template)
    r1 = max(r for r, c in template)
    c0 = min(c for r, c in template)
    c1 = max(c for r, c in template)
    cr, cc = (r0 + r1) // 2, (c0 + c1) // 2
    offsets = [(r - cr, c - cc, grid[r][c]) for r, c in template]

    out = [row[:] for row in grid]
    for r, c in markers:
        for dr, dc, color in offsets:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                out[nr][nc] = color
    return out
